import logging.handlers
import sys


def _install_windows_safe_rotating_file_handler():
    if sys.platform != "win32":
        return

    handler_cls = logging.handlers.RotatingFileHandler
    if getattr(handler_cls.doRollover, "_splunk_winerror32_safe", False):
        return

    original_do_rollover = handler_cls.doRollover

    def _splunk_safe_do_rollover(self):
        try:
            original_do_rollover(self)
        except OSError as e:
            if getattr(e, "winerror", None) != 32:
                raise
            # Multiple Windows processes can race while rotating the same log.
            # The process that loses the rename race should continue logging.
            pass

    _splunk_safe_do_rollover._splunk_winerror32_safe = True
    _splunk_safe_do_rollover._splunk_original_doRollover = original_do_rollover
    handler_cls.doRollover = _splunk_safe_do_rollover


_install_windows_safe_rotating_file_handler()
